// عقدة الشجرة: قيمة وطفلان
class TreeNode {
    int value
    TreeNode left, right
    TreeNode(int v) { value = v }
}

// إدراج قيمة في شجرة البحث الثنائية
static TreeNode insert(TreeNode root, int v) {
    if (root == null) return new TreeNode(v)
    if (v < root.value)
        root.left = insert(root.left, v)
    else if (v > root.value)
        root.right = insert(root.right, v)
    return root
}

// اجتياز بالترتيب: يسار، جذر، يمين
static void inOrder(TreeNode node) {
    if (node == null) return
    inOrder(node.left)
    print(node.value + ' ')
    inOrder(node.right)
}

