def gcd(a, b) {
    // نكرر الطرح حتى يصبح الباقي صفراً
    while (b != 0) {
        (a, b) = [b, a % b]
    }
    return a
}

// استخدام الإغلاق لتعريف الدالة بشكل مختصر
def gcdClosure = { x, y ->
    while (y) { (x, y) = [y, x % y] }
    x
}

println "GCD(48, 18) = ${gcd(48, 18)}"
println "GCD(56, 98) = ${gcdClosure(56, 98)}"

def fib(n) {
    if (n <= 1) return n
    def dp = [0, 1]
    // نملأ الجدول تصاعدياً
    for (i in 2..n) {
        dp[i] = dp[i-1] + dp[i-2]
    }
    return dp[n]
}

