// دالة عكس القائمة: نمرر الرأس ونعيد الرأس الجديد
static Node reverse(Node head) {
    Node prev = null
    Node curr = head
    while (curr != null) {
        Node next = curr.next  // نحفظ التالي قبل كسر الرابط
        curr.next = prev       // نقلب اتجاه المؤشر
        prev = curr
        curr = next
    }
    return prev
}

