def mergeSort(list) {
    if (list.size() <= 1) return list
    int mid = list.size().intdiv(2)
    def left = mergeSort(list[0..<mid])
    def right = mergeSort(list[mid..<list.size()])
    return merge(left, right)
}

def merge(left, right) {
    def result = []
    int i = 0, j = 0
    // ندمج القائمتين بالترتيب
    while (i < left.size() && j < right.size()) {
        if (left[i] <= right[j]) result << left[i++]
        else result << right[j++]
    }
    result.addAll(left[i..<left.size()])
    result.addAll(right[j..<right.size()])
    return result
}

