def pascal(int rows) {
    def triangle = [[1]]
    for (int i = 1; i < rows; i++) {
        def prev = triangle[-1]
        def next = [1] + (1..<prev.size()).collect { prev[it-1] + prev[it] } + [1]
        triangle << next
    }
    return triangle
}

