def quickSort(list, low, high) {
    if (low < high) {
        int pi = partition(list, low, high)
        quickSort(list, low, pi - 1)
        quickSort(list, pi + 1, high)
    }
}

def partition(list, low, high) {
    int pivot = list[high]
    int i = low - 1
    for (int j = low; j < high; j++) {
        if (list[j] <= pivot) {
            i++
            def temp = list[i]
            list[i] = list[j]
            list[j] = temp
        }
    }
    def temp = list[i + 1]
    list[i + 1] = list[high]
    list[high] = temp
    return i + 1
}

